const arrow = (href, text, className = "v3-link") => `<a class="${className}" href="${href}">${esc(text)}<span aria-hidden="true">↗</span></a>`;
const label = text => `<span class="v3-label">${esc(text)}</span>`;
const exhibit = (number, title, body, note = "", tone = "") => `<figure class="v3-exhibit ${tone}" role="img" aria-label="Exhibit ${number}: ${esc(title)}"><figcaption><span>${String(number).padStart(2, "0")}</span><strong>${esc(title)}</strong></figcaption>${body}${note ? `<p class="v3-exhibit-note">${esc(note)}</p>` : ""}</figure>`;

