const libraryEntry = (item, index) => `<a class="v3-library-entry" href="${item.href}" aria-label="Open ${esc(item.title)}" data-sector="${esc(item.sector)}" data-problem="${esc(item.problem)}" data-solution="${esc(item.solution)}"><span>${String(index + 1).padStart(2,"0")}</span><div><small>${esc(item.sector)} · ${esc(item.status)}</small><h3>${esc(item.title)}</h3><p>${esc(item.summary)}</p></div><dl><div><dt>Problem</dt><dd>${esc(item.problem)}</dd></div><div><dt>Solution</dt><dd>${esc(item.solution)}</dd></div></dl><b class="v3-entry-arrow" aria-hidden="true">↗</b></a>`;

export function v3UseLibrary(cases = libraryCases) {
  const groups = {
    sector: ["All","Banking & Fintech","Telecom","Retail & Consumer","Marketplaces","Enterprise Technology","Logistics","New Ventures"],
    problem: ["All","Growth","Profitability","New Revenue","Market Entry","Digital Transformation","AI Transformation","Operating Model","Customer Experience"],
    solution: ["All","Marketplace","Commerce","Payments","Loyalty","AI / Automation","Transformation","Venture","Platform","Operating Model"]
  };
  const filters = Object.entries(groups).map(([group,values])=>`<fieldset data-filter-set="${group}"><legend>${group === "sector" ? "Sector" : group === "problem" ? "Business problem" : "Solution type"}</legend><div>${values.map((value,index)=>`<button type="button" data-filter-group="${group}" data-filter-value="${esc(value)}" aria-pressed="${index === 0}">${esc(value)}</button>`).join("")}</div></fieldset>`).join("");
  return `<section class="v3-library-hero"><div class="v3-shell"><div>${label("Use-case library")}<h1>Business problems, commercial models and operating systems.</h1><p>An anonymized library across banking, telecom, retail, marketplaces, enterprise technology, logistics, ventures and AI.</p></div><aside><strong>${cases.length}</strong><span>public cases</span><p>Operating work, strategy blueprints and product concepts. Modeled outcomes remain separate from actual results.</p></aside></div></section>
  <section class="v3-library-feature"><div class="v3-shell"><img src="/assets/bank-commerce-concept.png" alt="Concept visualization of a bank commerce ecosystem" width="1680" height="945"><div>${label("Flagship case")}<h2>Saudi intelligent-commerce ecosystem</h2><p>Move a bank upstream from payment authorization into declared intent, eligible customer value and attributable merchant spend.</p><div class="v3-library-journey"><span>Intent</span><i></i><span>Eligibility</span><i></i><span>Value</span><i></i><span>Merchant</span><i></i><span>Spend</span></div>${arrow("/use-cases/leading-saudi-bank-commerce-ecosystem","Open the flagship case","v3-button light")}</div></div></section>
  <section class="v3-library-browser"><div class="v3-shell"><header class="v3-library-tools"><div><h2>Browse the library</h2><p>Combine sector, business problem and solution type. Every item opens a complete case page.</p></div><div class="v3-library-count"><strong id="case-count">${cases.length}</strong><span>cases shown</span></div></header><form class="v3-filter-panel" id="case-filters">${filters}<button class="v3-reset-filter" type="button" id="reset-filters">Reset filters</button></form><div class="v3-library-list" id="case-library">${cases.map(libraryEntry).join("")}</div><p class="v3-no-results" id="no-results" hidden>No cases match this combination.</p></div></section>
  <script>(()=>{const form=document.getElementById('case-filters');if(!form)return;const entries=[...document.querySelectorAll('.v3-library-entry')];const count=document.getElementById('case-count');const empty=document.getElementById('no-results');const state={sector:'All',problem:'All',solution:'All'};const apply=()=>{let visible=0;for(const entry of entries){const show=Object.entries(state).every(([group,value])=>value==='All'||entry.dataset[group]===value);entry.hidden=!show;if(show)visible++;}count.textContent=visible;empty.hidden=visible!==0;};form.addEventListener('click',event=>{const button=event.target.closest('[data-filter-value]');if(!button)return;const group=button.dataset.filterGroup;state[group]=button.dataset.filterValue;for(const peer of form.querySelectorAll('[data-filter-group="'+group+'"]'))peer.setAttribute('aria-pressed',String(peer===button));apply();});document.getElementById('reset-filters').addEventListener('click',()=>{for(const group of Object.keys(state)){state[group]='All';for(const button of form.querySelectorAll('[data-filter-group="'+group+'"]'))button.setAttribute('aria-pressed',String(button.dataset.filterValue==='All'));}apply();});})();</script>`;
}

const currentJourney = () => exhibit(1,"The bank enters after the commercial decision",`<div class="v3-current-journey"><div><span>Customer decision</span><b>Need</b><b>Category</b><b>Merchant</b></div><i></i><div class="late"><span>Bank appears</span><b>Authorization</b><b>Points posted</b></div><aside><strong>Influence already lost</strong><span>Intent</span><span>Merchant choice</span><span>Wallet share</span></aside></div>`,"Transaction data explains where the customer spent. It does not show which value would have changed the choice.","dark");
const futureJourney = () => exhibit(2,"A commerce-enabled journey starts at declared intent",`<div class="v3-future-journey">${[["01","Declare need"],["02","Resolve eligibility"],["03","Rank approved value"],["04","Explain and hand off"],["05","Match transaction"],["06","Measure incrementality"]].map(([n,t])=>`<div><span>${n}</span><b>${t}</b></div>`).join("")}</div>`,"The merchant remains responsible for product, price, checkout, fulfilment and returns.");
const ecosystem = () => exhibit(3,"Bank, merchant and customer ecosystem",`<div class="v3-bank-ecosystem"><div class="hub"><small>Orchestration</small><strong>Bank commerce layer</strong><span>Intent · Eligibility · Ranking · Attribution</span></div><div class="node customer"><small>Customer</small><b>Need, consent and choice</b></div><div class="node merchant"><small>Merchant</small><b>Product, service and funded value</b></div><div class="node products"><small>Bank products</small><b>Cards, loyalty and finance</b></div><div class="node control"><small>Bank operations</small><b>Settlement, risk and audit</b></div><svg viewBox="0 0 1000 500" aria-hidden="true"><path d="M500 250L170 95M500 250L830 95M500 250L170 405M500 250L830 405"/></svg></div>`,"The bank coordinates eligible value without taking over the retail transaction.","dark");
const economics = () => exhibit(4,"Commercial value pools and cost deductions",`<div class="v3-economics-waterfall">${[["Incremental card contribution",86,"add"],["Merchant funding",72,"add"],["Loyalty and finance value",58,"add"],["Customer benefit",45,"cost"],["Platform and service",35,"cost"],["Risk, returns, settlement",27,"cost"],["Net contribution",63,"result"]].map(([t,h,k])=>`<div class="${k}" style="--h:${h}%"><i></i><span>${t}</span></div>`).join("")}</div><div class="v3-equation"><span>Eligible demand</span><b>×</b><span>Conversion</span><b>×</b><span>Incremental basket</span><b>×</b><span>Net value rate</span><b>−</b><span>Cost to serve</span><b>=</b><strong>Net contribution</strong></div>`,"Conceptual economics only. Bar heights describe the model, not a forecast or achieved result.");
const architecture = () => exhibit(5,"Technology and data architecture",`<div class="v3-bank-architecture">${[["Experience","Bank app","Intent entry","Offer explanation","Merchant handoff"],["Decisioning","Card rules","Loyalty rules","Finance eligibility","AI ranking"],["Commerce services","Merchant offers","Handoff tokens","Campaign rules","Service metadata"],["Systems of record","Cards","Loyalty","Transactions","Merchant checkout"],["Control","Consent ledger","Attribution","Settlement","Model audit"]].map((row,index)=>`<div><span>0${index+1} · ${row[0]}</span>${row.slice(1).map(item=>`<b>${item}</b>`).join("")}</div>`).join("")}</div>`,"Live financial and retail facts remain in authoritative systems.","dark");
const aiLayer = () => exhibit(6,"AI ranks permitted value; policy controls eligibility",`<div class="v3-ai-layer"><div><span>Inputs</span><b>Declared intent</b><b>Eligible products</b><b>Approved offers</b><b>Merchant service</b></div><i>→</i><div class="policy"><span>Deterministic gate</span><strong>Permitted options only</strong><small>Consent · Credit · Campaign · Frequency</small></div><i>→</i><div class="rank"><span>AI decisioning</span><strong>Rank next best value</strong><small>Relevance · Customer value · Merchant quality · Contribution</small></div><i>→</i><div><span>Output</span><b>Ranked option</b><b>Reason code</b><b>Confidence</b><b>Alternative</b></div></div>`,"AI cannot approve finance, create eligibility, change rewards liability or override consent.");
const operating = () => exhibit(7,"Operating model and decision rights",`<div class="v3-operating-matrix">${[["Commerce product","Journey","Ranking objective","Pilot economics"],["Merchant operations","Offer readiness","Service failures","Funding files"],["Cards and loyalty","Eligibility","Benefit execution","Reversals"],["Risk, finance and data","Policy","Settlement","Model approval"]].map(row=>`<div><strong>${row[0]}</strong>${row.slice(1).map(item=>`<span>${item}</span>`).join("")}</div>`).join("")}</div><div class="v3-cadence"><span><b>Daily</b>Exceptions and service</span><span><b>Weekly</b>Commercial review</span><span><b>Monthly</b>Risk and finance</span><span><b>Gate</b>Scale, narrow or stop</span></div>`,"One product owner coordinates the journey. Specialist owners keep regulated and financial authority.","dark");
const roadmap = () => exhibit(8,"Twelve-month implementation roadmap",`<div class="v3-roadmap"><div class="scale"><span>0</span><span>3</span><span>6</span><span>9</span><span>12 months</span></div>${[["Commercial","Categories and anchor merchants","Pilot economics","Selective scale"],["Experience","Journey design","Employee and customer pilot","Category expansion"],["Technology","Eligibility, offers and events","Attribution and settlement","Automation"],["Control","Consent and policy","Testing and audit","Scale gates"]].map((row,index)=>`<div class="lane l${index+1}"><strong>${row[0]}</strong><span>${row[1]}</span><span>${row[2]}</span><span>${row[3]}</span></div>`).join("")}</div>`,"Expansion requires contribution, service quality, clean reconciliation and risk approval.");

export function v3Saudi({ item }) {
  return `<section class="v3-case-hero"><div class="v3-shell"><div>${label("Flagship strategy blueprint · Saudi Arabia · Modeled impact")}<h1>Move the bank upstream into purchase intent.</h1><p>A commerce ecosystem that connects card, loyalty, merchant and eligible finance value before checkout, then measures whether the journey changed customer spend.</p><div class="v3-case-facts"><span><b>Problem</b>The bank arrives after the choice.</span><span><b>Opportunity</b>Declared intent creates influence.</span><span><b>Control</b>Bank systems retain authority.</span></div></div><figure><img src="/assets/bank-commerce-concept.png" alt="Concept visualization of customer intent, merchant value and bank payment" width="1680" height="945"><figcaption>Concept illustration. No client branding or implementation claim.</figcaption></figure></div></section>
  <nav class="v3-case-nav" aria-label="Case chapters"><div class="v3-shell"><a href="#thesis">Thesis</a><a href="#journey">Journey</a><a href="#ecosystem">Ecosystem</a><a href="#economics">Economics</a><a href="#technology">Technology and AI</a><a href="#operating">Operating model</a><a href="#roadmap">Roadmap</a><a href="#measurement">Measurement</a></div></nav>
  <section class="v3-case-section v3-opening" id="thesis"><div class="v3-shell v3-narrative-aside"><div>${label("Executive summary")}<h2>The bank sees the payment, but the commercial decision was made earlier.</h2><p>By the time a card authorization reaches the bank, the customer has usually decided what to buy, narrowed the alternatives and selected a merchant. The bank can approve the transaction and post points, yet it has little influence over the choice that created the spend. Offer directories and post-purchase rewards sit downstream as well. They may reward activity, but they rarely connect a current customer need to relevant, eligible value.</p><p>The strategic move is to enter at declared purchase intent without turning the bank into a retailer. A customer starts with a need such as travel, electronics, home, education or a planned large purchase. The bank resolves which cards, rewards, merchant benefits or existing instalment routes are permitted. AI ranks those approved options and explains their relevance. The merchant retains responsibility for product, price, stock, checkout, fulfilment and returns.</p><p>The commercial opportunity is coordination rather than catalogue ownership. The bank already has trusted customer access, payment products, loyalty assets and merchant relationships. Their value is limited when they operate as separate campaigns. A thin commerce layer can assemble permitted value around a current need, route the customer to the merchant and preserve an event trail that supports attribution, return handling and settlement.</p><p>The value case combines incremental card contribution, merchant-funded demand, better use of loyalty assets, eligible finance value and stronger engagement with the bank's owned channels. Those pools only matter after customer benefit, merchant acquisition, platform integration, care, fraud, returns, settlement and operating capacity are deducted. Attributed spend is not treated as incremental until a control cohort shows a behavioural difference.</p><p>This is a strategy blueprint. No bank implementation, revenue result or customer uplift is claimed. The management decision is whether a controlled 90-day pilot can prove relevance, merchant service, clean attribution, funding reconciliation and positive modeled contribution at the same time.</p></div><aside class="v3-board-note"><span>Board decision</span><h3>Should the bank influence purchase intent before checkout?</h3><dl><div><dt>Build</dt><dd>A narrow intent and value layer inside an authenticated channel.</dd></div><div><dt>Avoid</dt><dd>A general marketplace, copied merchant catalogue or new credit engine.</dd></div><div><dt>Prove</dt><dd>Incremental spend, contribution, service quality and control.</dd></div><div><dt>Gate</dt><dd>Scale only after returns, rewards and merchant funding reconcile.</dd></div></dl></aside></div></section>
  <section class="v3-case-section" id="journey"><div class="v3-shell"><header class="v3-case-heading">${label("Business problem and customer journey")}<h2>Purchase intent forms before payment authorization.</h2><div><p>Customers compare categories, products and merchants across search, social platforms, marketplaces, brand sites and physical retail. Transaction history can describe past spend, but it cannot reliably explain the alternatives considered or the value that might have changed the choice.</p><p>The gap is the distance between valuable bank assets and the moment those assets can influence behaviour. Cards, loyalty balances, merchant relationships, trusted identity and eligible finance may all exist, yet the customer experiences them as separate products.</p><p>The status quo fragments accountability. Cards may own spend, loyalty may own rewards, marketing may own campaigns and merchant partnerships may own offers, while no team owns the complete path from intent to reconciled value. That fragmentation makes it difficult to compare customer benefit with merchant funding, service cost and incremental portfolio contribution.</p></div></header><div class="v3-exhibit-pair">${currentJourney()}${futureJourney()}</div><div class="v3-three-column"><article><h3>Cardholder segmentation</h3><p>Start with declared category, value sensitivity, product eligibility, location or fulfilment feasibility, loyalty balance, recent engagement and consented transaction patterns. Protected characteristics and unrelated sensitive data have no place in offer ranking. The pilot needs a small set of segments that product, risk and merchant teams can explain.</p></article><article><h3>Customer value</h3><p>The customer should see a short set of permitted options, not another campaign catalogue. Each option explains the benefit, conditions, merchant, payment route and whether rewards or existing instalment eligibility apply. The customer controls the final purchase and can withdraw consent.</p></article><article><h3>Merchant value</h3><p>Merchants receive qualified demand from identifiable needs rather than broad campaign traffic. They fund value against completed transactions or agreed campaign terms. The bank requires reliable offer data, recognizable descriptors, service ownership, return events and settlement evidence.</p></article></div></div></section>
  <section class="v3-case-section dark" id="ecosystem"><div class="v3-shell v3-section-split"><div><header class="v3-case-heading">${label("Solution design")}<h2>A coordination layer, not a bank-owned retailer.</h2></header><p>The customer layer captures intent and explains eligible value. The product layer resolves card, loyalty and finance rules. The merchant layer manages funded offers, handoff and service metadata. The measurement layer connects intent, offer view, merchant visit, authorization, return and settlement.</p><p>Role clarity protects the model. The merchant owns the retail transaction. The bank owns financial eligibility, consent, attribution and settlement. AI can rank permitted options but cannot create an entitlement, approve credit or change rewards liability.</p><div class="v3-principles"><span><b>Customer</b>Need, consent and choice</span><span><b>Bank</b>Eligibility, value and control</span><span><b>Merchant</b>Product, service and funded demand</span><span><b>Shared ledger</b>Attribution, returns and settlement</span></div></div>${ecosystem()}</div></section>
  <section class="v3-case-section" id="economics"><div class="v3-shell"><header class="v3-case-heading">${label("Commercial model")}<h2>Payment volume is activity. The decision rests on net incremental contribution.</h2><div><p>The first value pool is spend that moves to the bank's card portfolio or happens more often because relevant value appeared before checkout. The second is merchant funding: a fixed benefit, campaign contribution or completed-transaction acquisition fee tied to qualified demand. Loyalty and eligible finance can add value, but each has a separate funding source, product rule and accounting treatment.</p><p>Card economics differ by portfolio, transaction type and funding mix. The pilot therefore models contribution by cohort and category rather than applying one value rate to all payment volume. It distinguishes spend shifted from another bank, genuinely new spend, spend that would have happened on the same card anyway and transactions that become uneconomic after benefit cost.</p></div></header>${economics()}<div class="v3-commercial-grid"><article><h3>Merchant economics</h3><p>A merchant may fund a benefit because the bank supplies qualified demand, lowers acquisition cost or improves conversion in a priority category. The agreement defines the event that earns funding, how returns reverse it and when settlement occurs.</p></article><article><h3>Loyalty economics</h3><p>Points redeemed are not free value. The model records reward liability, customer benefit, engagement and incremental spend separately. A large unused balance does not justify a weak customer proposition.</p></article><article><h3>Financing opportunities</h3><p>Eligible instalment or financing routes can improve affordability and basket size, but only through existing credit policy, disclosure and underwriting. The commerce layer presents permitted value. It does not create an approval path.</p></article><article><h3>Cost to serve</h3><p>Customer benefit, acquisition, integration, customer care, fraud, disputes, returns, settlement and the fixed team all reduce contribution. Attributed spend can grow while value falls.</p></article></div></div></section>
  <section class="v3-case-section dark" id="technology"><div class="v3-shell"><header class="v3-case-heading">${label("Technology, data and AI")}<h2>Connect existing bank capabilities through controlled interfaces.</h2><div><p>The mobile app or authenticated web channel captures intent. API services call card, loyalty, offer and approved finance systems. A merchant gateway holds offer and handoff data without copying the merchant's full catalogue. An event layer connects intent, eligibility, offer view, merchant handoff, authorization, return and settlement.</p><p>A customer consent ledger records purpose, scope and withdrawal. Tokenized handoff IDs reduce the personal data shared with merchants. Card, loyalty and credit systems remain authoritative for financial facts. Merchant systems remain authoritative for product, price, stock, fulfilment and returns.</p></div></header><div class="v3-exhibit-pair">${architecture()}${aiLayer()}</div><div class="v3-ai-rights"><div><span>AI may</span><b>Rank permitted value</b><b>Explain a recommendation</b><b>Detect service or settlement exceptions</b><b>Prepare scenario evidence</b></div><div><span>AI may not</span><b>Approve credit</b><b>Create product eligibility</b><b>Change rewards liability</b><b>Override consent or policy</b></div><div><span>Human authority</span><b>Approve policy and new data</b><b>Suppress merchants or campaigns</b><b>Resolve consequential exceptions</b><b>Release the next scale gate</b></div></div></div></section>
  <section class="v3-case-section" id="operating"><div class="v3-shell v3-section-split"><div><header class="v3-case-heading">${label("Operating model and governance")}<h2>One product owner coordinates the journey. Specialist owners retain regulated authority.</h2></header><p>The proposition needs one accountable product owner, one pilot scorecard and one exception queue. Cards, loyalty, merchant partnerships, data, technology, risk, compliance, finance and customer care keep their specialist responsibilities, but they work through a shared cadence.</p><p>Merchant operations manage offer readiness, service failures and funding files. Attribution and settlement operations reconcile transactions, returns, rewards and merchant obligations. Customer care sees the same eligibility and offer evidence shown to the customer.</p><p>Governance separates commercial optimization from regulated authority. The product team can propose a ranking objective, merchant mix or campaign threshold. Risk and product owners approve eligibility and credit rules. Data governance approves purpose, features and retention. Finance approves funding recognition and reversal treatment.</p></div>${operating()}</div></section>
  <section class="v3-case-section dark" id="roadmap"><div class="v3-shell"><header class="v3-case-heading">${label("MVP and scale roadmap")}<h2>The first 90 days are an evidence programme.</h2><div><p>Days 0 to 30 establish categories, anchor merchants, eligible cohorts, consent, attribution policy, funding treatment and the executive scorecard. No customer pilot begins while returns, reward reversal or merchant settlement remain ambiguous.</p><p>Days 31 to 60 build the narrow journey, offer feed, eligibility calls, event IDs, operator view and reconciliation file. Employee testing proves that ineligible value is suppressed, customer care can read the evidence and returns reverse correctly.</p><p>Days 61 to 90 run a limited customer cohort with weekly stop, narrow or continue decisions. Months 4 to 12 depend on evidence. New categories, merchants, finance routes or self-service enter only when contribution, service, consent and operational control remain inside agreed thresholds.</p></div></header>${roadmap()}</div></section>
  <section class="v3-case-section" id="measurement"><div class="v3-shell"><header class="v3-case-heading">${label("Measurement and modeled impact")}<h2>The scorecard distinguishes engagement, attribution and incrementality.</h2><div><p>The executive view starts with eligible demand, then follows the event chain through intent, offer view, merchant handoff, completed transaction and repeat behaviour. It pairs those activity measures with service, control and economics. Incremental card spend, measured against a control, is the central commercial signal. Total attributed spend is not a substitute.</p><p>The business case should be expressed as a range. A base case models eligible customers, covered intent, conversion, basket, frequency and control lift. A downside case assumes lower incrementality, more cannibalization, higher service cost and slower merchant funding recovery. If the economics work only under optimistic attribution, the pilot should stop or remain narrow.</p><p>The scorecard also needs a timing view. Merchant funding may arrive after the transaction, returns may reverse value and loyalty accounting may follow another cycle. Finance should reconcile the programme by transaction cohort so a short-term engagement lift cannot hide delayed cost or settlement breaks.</p></div></header><div class="v3-kpi-table"><div><span>Reach and relevance</span><b>Eligible customers</b><b>Intent starts</b><b>Offer relevance</b><b>Frequency caps</b></div><div><span>Journey</span><b>Merchant handoff</b><b>Conversion</b><b>Repeat use</b><b>Service failure</b></div><div><span>Incrementality</span><b>Control lift</b><b>Wallet recapture</b><b>Incremental spend</b><b>Category lift</b></div><div><span>Economics</span><b>Merchant funding</b><b>Reward cost</b><b>Service cost</b><b>Net contribution</b></div><div><span>Trust and control</span><b>Consent withdrawal</b><b>Eligibility errors</b><b>Settlement breaks</b><b>Model overrides</b></div></div><div class="v3-impact-row"><article><span>Modeled business impact</span><p>${esc(item.impact)}</p><small>No achieved bank revenue, adoption or uplift is claimed.</small></article><article><h3>Risks and dependencies</h3><p>The case depends on clear consent, usable transaction descriptors, reliable return events, merchant service ownership, existing product eligibility services and finance-approved settlement treatment.</p><ul><li>Intent data used outside its approved purpose.</li><li>Existing spend credited to the programme.</li><li>Poor merchant stock, fulfilment or returns.</li><li>Benefits and funding that do not reconcile.</li><li>Ranking drift or concentration without commercial cause.</li><li>Reward and operating cost above incremental value.</li></ul></article></div><div class="v3-takeaways"><span>Enter at declared intent.</span><span>Resolve eligibility before ranking.</span><span>Keep retail responsibility with the merchant.</span><span>Measure incrementality against controls.</span><span>Reconcile before scaling.</span></div></div></section>`;
}

const authorityMatrix = () => `<div class="v3-authority-matrix"><div><span>Read</span><b>Summarize approved evidence</b><small>AI may act</small></div><div><span>Prepare</span><b>Draft a response or scenario</b><small>AI may act</small></div><div><span>Recommend</span><b>Rank permitted options</b><small>Human reviews</small></div><div><span>Execute</span><b>Use a named tool</b><small>Approval required</small></div><div><span>Automate</span><b>Act inside tested limits</b><small>Bounded authority</small></div></div>`;

export function v3Ai() {
  return `<section class="v3-ai-hero"><div class="v3-shell"><div>${label("AI & Transformation")}<h1>Operational AI, under control.</h1><p>Products and enterprise workflows built around reliable facts, bounded authority and measurable business economics.</p><div class="v3-ai-principles"><span>Start with the operating decision</span><span>Separate knowledge from live facts</span><span>Give agents narrow tools</span><span>Keep consequential authority named</span></div></div><figure class="v3-ai-orbit" aria-label="AI operating model"><strong>AI workflow</strong><span>Evidence</span><span>Policy</span><span>Human authority</span><span>Audited action</span></figure></div></section>
  <section class="v3-ai-product"><div class="v3-shell"><header>${label("Product 01 · In development")}<h2>AI Commerce Command Center</h2><p>A supervised control layer across catalogue, orders, sellers, inventory, customer care and finance. It pulls operating signals into one exception queue, prepares an evidence-backed recommendation and asks for approval before consequential action.</p><dl><div><dt>Problem</dt><dd>Signals are fragmented across commerce systems.</dd></div><div><dt>Decision</dt><dd>Which exception needs action now?</dd></div><div><dt>Authority</dt><dd>People approve money, customer and seller consequences.</dd></div></dl>${arrow("/ai-commerce","Open the product case")}</header>${productCommandUi()}</div></section>
  <section class="v3-ai-product ivory"><div class="v3-shell reverse"><header>${label("Product 02 · Live")}<h2>Career Runway AI</h2><p>A private decision tool that connects a career choice to financial runway and personal trade-offs. Deterministic calculations keep the money model stable. AI structures scenarios and explains assumptions without taking the choice away from the user.</p><dl><div><dt>Problem</dt><dd>Career decisions are discussed without the cash reality.</dd></div><div><dt>Decision</dt><dd>Which path remains viable under different assumptions?</dd></div><div><dt>Authority</dt><dd>The user owns the final choice.</dd></div></dl>${arrow("/career-runway","Open the product case")}</header>${runwayUi()}</div></section>
  <section class="v3-ai-product"><div class="v3-shell"><header>${label("Product 03 · Product concept")}<h2>AEOFind</h2><p>A diagnostic product for finding gaps in how AI answer engines cover commercially important questions. It starts with a fixed intent set, tests answer coverage and evidence, then turns weak coverage into a prioritized content and authority plan.</p><dl><div><dt>Problem</dt><dd>Visibility reports do not explain answer-level gaps.</dd></div><div><dt>Decision</dt><dd>Which intent and evidence gap deserves action?</dd></div><div><dt>Authority</dt><dd>People approve the source and publication plan.</dd></div></dl>${arrow("/use-cases/aeofind","Open the product case")}</header>${aeoUi()}</div></section>
  <section class="v3-ai-architecture" id="architecture"><div class="v3-shell"><header class="v3-section-intro split">${label("Enterprise AI architecture")}<h2>Knowledge, live facts and authority are separate layers.</h2><p>Retrieval supplies approved knowledge. APIs supply facts that change. Agents use named tools inside explicit permissions and an auditable workflow.</p></header><figure class="v3-agent-stack" aria-label="Enterprise AI workflow architecture"><div><span>Inputs</span><b>Approved knowledge</b><b>Live operational APIs</b><b>Event stream</b><b>User context and consent</b></div><div class="accent"><span>Orchestration</span><b>Task scope</b><b>Policy</b><b>State</b><b>Tool permissions</b></div><div><span>Agent actions</span><b>Retrieve</b><b>Analyze</b><b>Recommend</b><b>Request approval</b><b>Execute</b></div><div><span>Control plane</span><b>Identity</b><b>Audit</b><b>Evaluation</b><b>Cost</b><b>Rollback</b></div><div><span>Business workflows</span><b>Commerce</b><b>Customer care</b><b>Finance</b><b>Management decisions</b></div></figure>${authorityMatrix()}</div></section>
  <section class="v3-ai-delivery"><div class="v3-shell"><div>${label("Delivery model")}<h2>From workflow evidence to governed scale.</h2><p>A useful AI programme starts with one process and a value measure. The first deployment stays narrow enough to evaluate, reverse and govern.</p></div><ol><li><span>01</span>Choose one decision and baseline its cost.</li><li><span>02</span>Connect approved knowledge and live facts.</li><li><span>03</span>Define tools, permissions and human authority.</li><li><span>04</span>Run a controlled workflow pilot.</li><li><span>05</span>Measure accuracy, service, economics and failure.</li><li><span>06</span>Expand authority only after the evidence holds.</li></ol></div></section>`;
}

export { libraryCases };
